SELECT cr.cr_return_quantity, cr.cr_return_amount, cr.cr_return_amount * cr.cr_return_tax AS tax_amount, cr.cr_return_amount + cr.cr_return_tax + cr.cr_return_ship_cost AS total_cost, CASE WHEN cr.cr_return_amount > 3888.31 THEN 'high' WHEN cr.cr_return_amount > 1603.95 THEN 'medium' ELSE 'low' END AS amount_category, CASE ca.ca_state WHEN 'CA' THEN 'West' WHEN 'NY' THEN 'East' ELSE 'Other' END AS region, (cr.cr_return_quantity * cr.cr_return_amount) - cr.cr_fee AS net_return, COALESCE(ca.ca_gmt_offset, 0) + -5.00 AS adjusted_offset, CONCAT(ca.ca_city, ', ', ca.ca_state) AS city_state FROM catalog_returns cr JOIN customer_address ca ON cr.cr_refunded_addr_sk = ca.ca_address_sk
